/* ============================================================
   EARTH DATA — loaded on demand by art-earth.js, never by the page itself,
   so a lab that shows no globe costs nothing.

   day   NASA Blue Marble: Next Generation, "world.topo.bathy" (NASA Earth
         Observatory / Visible Earth; public domain), as distributed in
         matplotlib basemap-data 2.0.0 (bmng.jpg, MIT for that file),
         resampled to 2048 x 1024, equirectangular, longitude -180..180.
   land  land/water mask rasterised from Natural Earth 1:50m land polygons
         (public domain), via world-atlas 2.0.2 (ISC), 2048 x 1024, same grid.
         Area-weighted land fraction of the mask: 29.1 percent (Earth: 29.2).
   ============================================================ */
window.EARTHDATA = {
  width: 2048, height: 1024,
  day: 'data:image/jpeg;base64,',
  land: 'data:image/png;base64,'
};
